<?php
require_once '../config/app.php';require_once '../includes/security.php';start_secure_session();require_permission('sources.view');$pdo=db();$tab=$_GET['tab']??'ready';if(!in_array($tab,['ready','review','failed'],true))$tab='ready';
$ready=$review=$failed=[];
try{$ready=$pdo->query("SELECT d.*,s.source_name,l.status ai_status,j.job_uid,j.job_title FROM source_documents d JOIN job_sources s ON s.id=d.source_id LEFT JOIN ai_extraction_logs l ON l.id=d.extraction_log_id LEFT JOIN jobs j ON j.id=d.job_id WHERE d.extraction_status='job_created' OR l.status='ready' ORDER BY d.last_seen_at DESC LIMIT 100")->fetchAll();}catch(Throwable $e){}
try{$review=$pdo->query("SELECT d.*,s.source_name,l.id log_id,l.status ai_status,l.created_at ai_created FROM source_documents d JOIN job_sources s ON s.id=d.source_id LEFT JOIN ai_extraction_logs l ON l.id=d.extraction_log_id WHERE d.extraction_status IN ('review','pending') OR l.status='review' ORDER BY d.last_seen_at DESC LIMIT 100")->fetchAll();}catch(Throwable $e){}
try{$failed=$pdo->query("SELECT d.*,s.source_name FROM source_documents d JOIN job_sources s ON s.id=d.source_id WHERE d.extraction_status='failed' ORDER BY d.last_seen_at DESC LIMIT 100")->fetchAll();}catch(Throwable $e){}
$scanFails=[];try{$scanFails=$pdo->query("SELECT l.*,s.source_name FROM source_scan_logs l JOIN job_sources s ON s.id=l.source_id WHERE l.status='failed' ORDER BY l.started_at DESC LIMIT 50")->fetchAll();}catch(Throwable $e){}
$page_title='AI Discovery Queue';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';?>
<div class="page-head"><div><span class="eyebrow">AI JOB DISCOVERY</span><h1>Discovery Queue</h1><p class="muted">Keep automatic jobs, uncertain extraction and failures separated so staff only handles exceptions.</p></div><a class="btn btn-light" href="sources.php">Source Manager</a></div>
<div class="queue-tabs"><a class="<?= $tab==='ready'?'active':''?>" href="?tab=ready">🟢 AI Ready <b><?=count($ready)?></b></a><a class="<?= $tab==='review'?'active':''?>" href="?tab=review">🟡 Review Required <b><?=count($review)?></b></a><a class="<?= $tab==='failed'?'active':''?>" href="?tab=failed">🔴 Failed / Manual <b><?=count($failed)+count($scanFails)?></b></a></div>
<?php if($tab==='ready'):?><div class="card"><div class="card-head"><div><h2>AI Ready Jobs</h2><p class="muted">High-confidence discoveries remain Pending Verification; nothing is auto-published.</p></div></div><div class="table-wrap"><table><tr><th>Source</th><th>Document</th><th>Job</th><th>AI Status</th><th>Detected</th></tr><?php foreach($ready as $r):?><tr><td><?=e($r['source_name'])?></td><td><a href="<?=e($r['source_url'])?>" target="_blank" rel="noopener">Open source ↗</a></td><td><?=e($r['job_title']?:'Ready for review')?><br><small><?=e($r['job_uid']?:'No job created')?></small></td><td><span class="tag"><?=e($r['ai_status']?:'ready')?></span></td><td><?=e($r['last_seen_at'])?></td></tr><?php endforeach;if(!$ready):?><tr><td colspan="5" class="muted">No AI-ready discoveries yet.</td></tr><?php endif;?></table></div></div>
<?php elseif($tab==='review'):?><div class="card"><div class="card-head"><div><h2>Review Required</h2><p class="muted">AI could read the document, but confidence or completeness needs human review.</p></div></div><div class="table-wrap"><table><tr><th>Source</th><th>Document</th><th>AI Status</th><th>Created</th><th>Action</th></tr><?php foreach($review as $r):?><tr><td><?=e($r['source_name'])?></td><td><a href="<?=e($r['source_url'])?>" target="_blank" rel="noopener">Open ↗</a></td><td><span class="tag"><?=e($r['ai_status']?:'review')?></span></td><td><?=e($r['ai_created']?:$r['last_seen_at'])?></td><td><?php if(!empty($r['log_id'])):?><a class="btn btn-small btn-primary" href="ai-review.php?log=<?=e($r['log_id'])?>">Review AI</a><?php else:?><span class="muted">Pending extraction</span><?php endif;?></td></tr><?php endforeach;if(!$review):?><tr><td colspan="5" class="muted">Review queue is clear.</td></tr><?php endif;?></table></div></div>
<?php else:?><div class="card"><div class="card-head"><div><h2>Failed / Manual Feed</h2><p class="muted">Blocked pages, unreadable PDFs or failed extraction belong here.</p></div><a class="btn btn-primary" href="job-intake.php">Manual Job Intake →</a></div><div class="table-wrap"><table><tr><th>Source</th><th>URL</th><th>Problem</th><th>Last Seen</th></tr><?php foreach($failed as $r):?><tr><td><?=e($r['source_name'])?></td><td><a href="<?=e($r['source_url'])?>" target="_blank" rel="noopener">Open ↗</a></td><td>Document extraction failed</td><td><?=e($r['last_seen_at'])?></td></tr><?php endforeach;foreach($scanFails as $r):?><tr><td><?=e($r['source_name'])?></td><td>Source scan</td><td><?=e($r['error_message']?:'Unknown scan error')?></td><td><?=e($r['started_at'])?></td></tr><?php endforeach;if(!$failed&&!$scanFails):?><tr><td colspan="4" class="muted">No failed scans or documents.</td></tr><?php endif;?></table></div></div><?php endif;?>
<?php require '../includes/footer.php';?>
